1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15	)
16	
17	// on-disk layout inside the data directory:
18	//
19	//	data.json    – the committed state (JSON envelope, atomically replaced)
20	//	data.json.tmp– staging file for the next commit (rename(2) target)
21	//	lock         – flock file serializing concurrent processes
22	//
23	// The envelope carries an explicit format version: files written by an
24	// incompatible future build are refused rather than silently migrated or
25	// overwritten.
26	const (
27		dirDataFile = "data.json"
28		dirTmpFile  = "data.json.tmp"
29		dirLockFile = "lock"
30	
31		// FormatVersion is the on-disk format this build writes and accepts.
32		FormatVersion = 1
33	)
34	
35	// envelope is the persisted state container.
36	//
37	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
38	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
39	// decides what a committed circuit record may look like. UnmarshalJSON first
40	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
41	// object key anywhere encoding/json would otherwise keep the last value. At
42	// the envelope's top level that comparison is case-insensitive for the five
43	// known fields (format/circuits/setups/jobs/artifacts): a second spelling
44	// that differs only in ASCII letter case — including one JSON-escaped — names
45	// the same field and corrupts the read instead of overriding it.
46	type envelope struct {
47		Format    int               `json:"format"`
48		Circuits  []persistCircuit  `json:"circuits"`
49		Setups    []persistSetup    `json:"setups"`
50		Jobs      []persistJob      `json:"jobs"`
51		Artifacts []persistArtifact `json:"artifacts,omitempty"`
52	}
53	
54	// envelopeWire is the decoding-only shape: circuit records arrive raw so
55	// their own strict decoder can require every field explicitly.
56	type envelopeWire struct {
57		Format    int               `json:"format"`
58		Circuits  []json.RawMessage `json:"circuits"`
59		Setups    []persistSetup    `json:"setups"`
60		Jobs      []persistJob      `json:"jobs"`
61		Artifacts []persistArtifact `json:"artifacts,omitempty"`
62	}
63	
64	func (e *envelope) UnmarshalJSON(raw []byte) error {
65		// Reject repeated keys before decoding: encoding/json silently keeps the
66		// last value of a duplicate. The walk is layered so a repeated field is
67		// attributed to the record it belongs to (a duplicate "frozen" inside
68		// circuit #3, not a generic envelope complaint).
69		if err := scanEnvelopeDuplicates(raw); err != nil {
70			return err
71		}
72		var wire envelopeWire
73		if err := json.Unmarshal(raw, &wire); err != nil {
74			var se StoreError
75			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
76				return err // an inner record decoder already named the problem
77			}
78			return corruptf("data file envelope is not valid JSON: %v", err)
79		}
80		e.Format = wire.Format
81		e.Setups = wire.Setups
82		e.Jobs = wire.Jobs
83		e.Artifacts = wire.Artifacts
84		if wire.Circuits == nil {
85			e.Circuits = nil
86		} else {
87			e.Circuits = make([]persistCircuit, len(wire.Circuits))
88		}
89		for i, craw := range wire.Circuits {
90			var record persistCircuit
91			if err := json.Unmarshal(craw, &record); err != nil {
92				var se StoreError
93				if errors.As(err, &se) {
94					// Re-tag as one corruption error carrying the record index,
95					// so the detail survives errors.As unwrapping in loadLocked.
96					return StoreError{Kind: ErrDataCorrupt.Kind,
97						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
98				}
99				return corruptf("circuit record #%d: %v", i+1, err)
100			}
101			e.Circuits[i] = record
102		}
103		return nil
104	}
105	
106	// envelopeTopFields are the five fields an envelope may carry. Their
107	// canonical (standard lowercase) spellings are the wire tags on envelope and
108	// envelopeWire; JSON keys are tokenized after unescaping.
109	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
110	
111	// canonicalEnvelopeField reports the standard lowercase name of one of the
112	// five envelope fields when key names it under any ASCII letter-case spelling
113	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
114	// tokenizer, so an escaped spelling of any such form lands here too. A
115	// non-canonical key (different length or a mismatching byte, including
116	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
117	func canonicalEnvelopeField(key string) string {
118		for _, field := range envelopeTopFields {
119			if len(key) != len(field) {
120				continue
121			}
122			i := 0
123			for i < len(key) {
124				c := key[i]
125				if c >= 'A' && c <= 'Z' {
126					c += 'a' - 'A'
127				}
128				if c != field[i] {
129					break
130				}
131				i++
132			}
133			if i == len(field) {
134				return field
135			}
136		}
137		return ""
138	}
139	
140	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
141	// repeated object key. The five known top-level fields are identified case-
142	// insensitively: two spellings that differ only in ASCII letter case (both
143	// keys already JSON-unescaped at this point) are the same field, in whatever
144	// order they appear and whether or not their values agree, so a later
145	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
146	// json's last-value-wins struct matching. Such a pair is reported as a
147	// duplicated top-level field named by its standard lowercase spelling.
148	//
149	// Circuit records are scanned one level deep only — their top-level fields
150	// are checked here (with the record's 1-based index reported), while values
151	// such as the constraint definition are skipped and left to their own strict
152	// decoders. Every other envelope member is scanned recursively so a
153	// duplicated key anywhere in committed data fails the read instead of
154	// silently resolving to its last value.
155	func scanEnvelopeDuplicates(raw []byte) error {
156		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
157		dec.UseNumber()
158		open, err := dec.Token()
159		if err != nil || open != json.Delim('{') {
160			return corruptf("data file envelope must be a JSON object")
161		}
162		// Exact spellings retain the pre-existing check for unknown keys;
163		// canonical names remember a known field's first occurrence regardless
164		// of the case it was written in.
165		seenTop := make(map[string]bool)
166		seenCanonical := make(map[string]bool)
167		for dec.More() {
168			keyTok, err := dec.Token()
169			if err != nil {
170				return corruptf("data file envelope is not valid JSON: %v", err)
171			}
172			key, ok := keyTok.(string)
173			if !ok {
174				return corruptf("data file envelope is not valid JSON")
175			}
176			if canonical := canonicalEnvelopeField(key); canonical != "" {
177				if seenCanonical[canonical] {
178					if key == canonical {
179						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
180					}
181					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
182						canonical, key)
183				}
184				seenCanonical[canonical] = true
185				if canonical == "circuits" {
186					if err := scanCircuitArrayDuplicates(dec); err != nil {
187						return err
188					}
189					continue
190				}
191				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
192					return err
193				}
194				continue
195			}
196			if seenTop[key] {
197				return corruptf("data file envelope contains duplicate field %q", key)
198			}
199			seenTop[key] = true
200			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
201				return err
202			}
203		}
204		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
205			return corruptf("data file envelope is not valid JSON")
206		}
207		if _, err := dec.Token(); err != io.EOF {
208			return corruptf("data file envelope is not valid JSON: trailing data after the object")
209		}
210		return nil
211	}
212	
213	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
214	// opening bracket and checks only each record's own top-level keys. The
215	// enclosing key may carry any case spelling, but the field it names is the
216	// canonical "circuits". A null array stays the pre-existing "no records"
217	// reading.
218	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
219		tok, err := dec.Token()
220		if err != nil {
221			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
222		}
223		if tok == nil { // null: json.Unmarshal would produce no records
224			return nil
225		}
226		if tok != json.Delim('[') {
227			return corruptf("data file envelope field \"circuits\" must be an array")
228		}
229		index := 0
230		for dec.More() {
231			index++
232			what := fmt.Sprintf("circuit record #%d", index)
233			open, err := dec.Token()
234			if err != nil {
235				return corruptf("%s is not valid JSON: %v", what, err)
236			}
237			if open == nil {
238				return corruptf("%s must be a JSON object, not null", what)
239			}
240			if open != json.Delim('{') {
241				return corruptf("%s must be a JSON object", what)
242			}
243			seen := make(map[string]bool)
244			for dec.More() {
245				keyTok, err := dec.Token()
246				if err != nil {
247					return corruptf("%s is not valid JSON: %v", what, err)
248				}
249				key, ok := keyTok.(string)
250				if !ok {
251					return corruptf("%s is not valid JSON", what)
252				}
253				if seen[key] {
254					return corruptf("%s contains duplicate field %q", what, key)
255				}
256				seen[key] = true
257				// Skip the whole value without descending: nested objects
258				// (definition) own their own strict duplicate checks.
259				var skip json.RawMessage
260				if err := dec.Decode(&skip); err != nil {
261					return corruptf("%s is not valid JSON: %v", what, err)
262				}
263			}
264			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
265				return corruptf("%s is not valid JSON", what)
266			}
267		}
268		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
269			return corruptf("data file envelope field \"circuits\" is not valid JSON")
270		}
271		return nil
272	}
273	
274	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
275	// recursively rejecting duplicate object keys.
276	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
277		tok, err := dec.Token()
278		if err != nil {
279			return corruptf("%s is not valid JSON: %v", what, err)
280		}
281		delim, ok := tok.(json.Delim)
282		if !ok {
283			return nil // scalar (including null)
284		}
285		switch delim {
286		case '{':
287			seen := make(map[string]bool)
288			for dec.More() {
289				keyTok, err := dec.Token()
290				if err != nil {
291					return corruptf("%s is not valid JSON: %v", what, err)
292				}
293				key, ok := keyTok.(string)
294				if !ok {
295					return corruptf("%s is not valid JSON", what)
296				}
297				if seen[key] {
298					return corruptf("%s contains duplicate field %q", what, key)
299				}
300				seen[key] = true
301				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
302					return err
303				}
304			}
305			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
306				return corruptf("%s is not valid JSON", what)
307			}
308		case '[':
309			index := 0
310			for dec.More() {
311				index++
312				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
313					return err
314				}
315			}
316			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
317				return corruptf("%s is not valid JSON", what)
318			}
319		}
320		return nil
321	}
322	
323	type persistTerm struct {
324		Wire  int    `json:"wire"`
325		Coeff string `json:"coeff"`
326	}
327	
328	type persistConstraint struct {
329		A []persistTerm `json:"a"`
330		B []persistTerm `json:"b"`
331		C []persistTerm `json:"c"`
332	}
333	
334	// persistDefinition is the canonical, already-validated constraint set bound
335	// to one circuit version. The public/private partition is owned by the
336	// circuit record and is deliberately not duplicated here, so it can never
337	// drift from the declared counts.
338	type persistDefinition struct {
339		Modulus     string              `json:"modulus"`
340		Constraints []persistConstraint `json:"constraints"`
341	}
342	
343	// persistArtifact is a compiled artifact: the version's identity and
344	// constraint count bound to its recomputable SHA-256 hash.
345	type persistArtifact struct {
346		Name        string `json:"name"`
347		Version     int    `json:"version"`
348		Modulus     int64  `json:"modulus"`
349		Constraints int    `json:"constraints"`
350		Hash        string `json:"hash"`
351	}
352	
353	type persistCircuit struct {
354		Name          string             `json:"name"`
355		Version       int                `json:"version"`
356		Constraints   int                `json:"constraints"`
357		PublicInputs  int                `json:"public_inputs"`
358		PrivateInputs int                `json:"private_inputs"`
359		Frozen        bool               `json:"frozen"`
360		Description   string             `json:"description"`
361		Definition    *persistDefinition `json:"definition,omitempty"`
362	}
363	
364	// Strict decoding of committed circuit records.
365	//
366	// A circuit record in data.json must name each of name, version, constraints,
367	// public_inputs, private_inputs, frozen and description exactly once, with
368	// the exact JSON type the writer emits (string / integer / integer / integer
369	// / integer / boolean / string). A missing key, a null, a wrong type or a
370	// repeated key is data corruption and refuses the whole directory read: a
371	// missing or null frozen flag must not silently read as false (turning a
372	// frozen version back into an editable draft), and a repeated key must not
373	// resolve to its last value. An explicit 0, false or "" is an ordinary value
374	// and stays legal. The definition member remains the one optional field: it
375	// may be absent or null (the legacy counts-only state); when present it goes
376	// through the strict persistDefinition decoder.
377	//
378	// Only shape is judged here. The domain rules (non-blank name, positive
379	// version and constraint count, non-negative input counts) keep being
380	// re-checked by validateEnvelope.
381	
382	var persistCircuitFields = []string{
383		"name", "version", "constraints", "public_inputs", "private_inputs",
384		"frozen", "description", "definition",
385	}
386	
387	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
388	// tagged for committed data: every structural failure in a stored circuit
389	// record is data corruption, never a bad request.
390	var storedRecordShape = jsonShape{fail: corruptf}
391	
392	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
393		const what = "stored circuit record"
394		if string(bytes.TrimSpace(raw)) == "null" {
395			return corruptf("%s must be a JSON object, not null", what)
396		}
397		members, err := strictCircuitObject(raw, what)
398		if err != nil {
399			return err
400		}
401	
402		var out persistCircuit
403	
404		requireString := func(key string, dst *string) error {
405			r, err := storedRecordShape.require(members, key, what)
406			if err != nil {
407				return err
408			}
409			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
410			if err != nil {
411				return err
412			}
413			*dst = v
414			return nil
415		}
416		requireInt := func(key string, dst *int) error {
417			r, err := storedRecordShape.require(members, key, what)
418			if err != nil {
419				return err
420			}
421			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
422			if err != nil {
423				return err
424			}
425			*dst = v
426			return nil
427		}
428	
429		if err := requireString("name", &out.Name); err != nil {
430			return err
431		}
432		if err := requireInt("version", &out.Version); err != nil {
433			return err
434		}
435		if err := requireInt("constraints", &out.Constraints); err != nil {
436			return err
437		}
438		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
439			return err
440		}
441		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
442			return err
443		}
444		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
445		if err != nil {
446			return err
447		}
448		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
449		if err != nil {
450			return err
451		}
452		if err := requireString("description", &out.Description); err != nil {
453			return err
454		}
455	
456		// definition is the only optional member: absent or null both mean the
457		// counts-only legacy state.
458		if defRaw, present := members["definition"]; present {
459			if string(bytes.TrimSpace(defRaw)) != "null" {
460				var def persistDefinition
461				if err := json.Unmarshal(defRaw, &def); err != nil {
462					var se StoreError
463					if errors.As(err, &se) {
464						return err // already reported as data corruption
465					}
466					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
467				}
468				out.Definition = &def
469			}
470		}
471	
472		*c = out
473		return nil
474	}
