1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"strconv"
11		"strings"
12		"testing"
13	)
14	
15	// These tests pin the top-level envelope rule for the five committed fields
16	// (format, circuits, setups, jobs, artifacts): a difference in ASCII letter
17	// case only — including a difference hidden behind a JSON string escape —
18	// still names the same field. Two such spellings in one envelope corrupt the
19	// whole directory read, regardless of order or of whether the two values
20	// agree, while a single spelling in any case variant keeps reading exactly as
21	// the lowercase canonical key would.
22	
23	// envKv is one top-level envelope member read in document order: keyToken is
24	// the exact JSON key token to emit (quotes included, escapes preserved) and
25	// val is its raw JSON value.
26	type envKv struct {
27		keyToken string
28		val      json.RawMessage
29	}
30	
31	// readOrderedEnvelope tokenizes data.json into its ordered top-level members
32	// without a map, so a test can re-emit the envelope with chosen key spellings
33	// and a chosen member order.
34	func readOrderedEnvelope(t *testing.T, dir string) []envKv {
35		t.Helper()
36		raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
37		if err != nil {
38			t.Fatal(err)
39		}
40		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
41		dec.UseNumber()
42		open, err := dec.Token()
43		if err != nil || open != json.Delim('{') {
44			t.Fatalf("seeded envelope is not an object: %v", err)
45		}
46		var kvs []envKv
47		for dec.More() {
48			keyTok, err := dec.Token()
49			if err != nil {
50				t.Fatal(err)
51			}
52			var val json.RawMessage
53			if err := dec.Decode(&val); err != nil {
54				t.Fatal(err)
55			}
56			kvs = append(kvs, envKv{keyToken: strconv.Quote(keyTok.(string)), val: val})
57		}
58		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
59			t.Fatalf("seeded envelope is not valid JSON: %v", err)
60		}
61		return kvs
62	}
63	
64	// envelopeValues indexes the seeded envelope's values by canonical key.
65	func envelopeValues(kvs []envKv) map[string]json.RawMessage {
66		vals := make(map[string]json.RawMessage, len(kvs))
67		for _, kv := range kvs {
68			var key string
69			if err := json.Unmarshal([]byte(kv.keyToken), &key); err != nil {
70				panic(err)
71			}
72			vals[key] = kv.val
73		}
74		return vals
75	}
