77	// writeEnvelope emits members in the given order, compacting values, and
78	// returns the bytes now on disk.
79	func writeEnvelope(t *testing.T, dir string, kvs []envKv) []byte {
80		t.Helper()
81		var buf bytes.Buffer
82		buf.WriteByte('{')
83		for i, kv := range kvs {
84			if i > 0 {
85				buf.WriteByte(',')
86			}
87			buf.WriteString(kv.keyToken)
88			buf.WriteByte(':')
89			var compact bytes.Buffer
90			if err := json.Compact(&compact, kv.val); err != nil {
91				t.Fatalf("envelope value is not valid JSON: %v", err)
92			}
93			buf.Write(compact.Bytes())
94		}
95		buf.WriteString("}\n")
96		out := buf.Bytes()
97		if err := os.WriteFile(filepath.Join(dir, dirDataFile), out, 0o644); err != nil {
98			t.Fatal(err)
99		}
100		return out
101	}
