144	// requireTopLevelDupCorrupt opens dir, requires a data-corrupt error that
145	// names both the duplicated top-level field (canonical lowercase) and its
146	// actual second spelling, and requires data.json to stay byte-for-byte.
147	func requireTopLevelDupCorrupt(t *testing.T, dir string, bad []byte, canonical, secondToken string) {
148		t.Helper()
149		s, err := Open(dir)
150		if err == nil {
151			s.Close()
152			t.Fatalf("duplicate case-variant top-level field %q was accepted", canonical)
153		}
154		var se StoreError
155		if !errors.As(err, &se) || se.Kind != ErrDataCorrupt.Kind {
156			t.Fatalf("want ErrDataCorrupt, got %v", err)
157		}
158		msg := err.Error()
159		if !strings.Contains(msg, "duplicate top-level field") {
160			t.Fatalf("error does not identify a duplicated top-level field: %v", err)
161		}
162		if !strings.Contains(msg, strconv.Quote(canonical)) {
163			t.Fatalf("error does not name the canonical field %q: %v", canonical, err)
164		}
165		var second string
166		if uerr := json.Unmarshal([]byte(secondToken), &second); uerr == nil && second != canonical {
167			if !strings.Contains(msg, strconv.Quote(second)) {
168				t.Fatalf("error does not name the second spelling %q: %v", second, err)
169			}
170		}
171		left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
172		if rerr != nil {
173			t.Fatal(rerr)
174		}
175		if string(left) != string(bad) {
176			t.Fatalf("refused read modified data.json\nwant: %q\n got: %q", bad, left)
177		}
178		if s2, err := Open(dir); err == nil {
179			s2.Close()
180			t.Fatalf("reopen accepted the duplicated top-level field")
181		} else if !errors.Is(err, ErrDataCorrupt) {
182			t.Fatalf("reopen: want ErrDataCorrupt, got %v", err)
183		}
184	}
