269	// TestTopLevelDuplicateCannotPickAValue covers the dangerous value shapes:
270	// a complete record beside an empty array or null (both orders), an
271	// unsupported format number beside 1 (both orders), and an array of illegal
272	// records beside an empty array. Neither side may be selected.
273	func TestTopLevelDuplicateCannotPickAValue(t *testing.T) {
274		illegalRecord := json.RawMessage(`[{"name":"mul","version":1,"constraints":1,` +
275			`"public_inputs":1,"private_inputs":1,"description":"x"}]`) // missing "frozen"
276	
277		cases := []struct {
278			name      string
279			field     string
280			first     json.RawMessage // appears first
281			second    json.RawMessage // appears last
282			reversed  bool            // upper-case spelling comes first, canonical last
283			wantField string
284		}{
285			{"full circuits then empty", "circuits", nil, json.RawMessage("[]"), false, "circuits"},
286			{"empty circuits then full", "circuits", json.RawMessage("[]"), nil, true, "circuits"},
287			{"full circuits then null", "circuits", nil, json.RawMessage("null"), false, "circuits"},
288			{"null circuits then full", "circuits", json.RawMessage("null"), nil, true, "circuits"},
289			{"bad-record circuits beside empty", "circuits", illegalRecord, json.RawMessage("[]"), false, "circuits"},
290			{"empty beside bad-record circuits", "circuits", json.RawMessage("[]"), illegalRecord, true, "circuits"},
291			{"format 1 then 999", "format", json.RawMessage("1"), json.RawMessage("999"), false, "format"},
292			{"format 999 then 1", "format", json.RawMessage("999"), json.RawMessage("1"), true, "format"},
293			{"format 1 then null", "format", json.RawMessage("1"), json.RawMessage("null"), false, "format"},
294			{"setups full then null", "setups", nil, json.RawMessage("null"), false, "setups"},
295			{"jobs empty then full", "jobs", json.RawMessage("[]"), nil, true, "jobs"},
296			{"artifacts null then full", "artifacts", json.RawMessage("null"), nil, true, "artifacts"},
297		}
298		for _, tc := range cases {
299			t.Run(tc.name, func(t *testing.T) {
300				dir, _ := seedBoundStore(t)
301				vals := envelopeValues(readOrderedEnvelope(t, dir))
302				first, second := tc.first, tc.second
303				if first == nil {
304					first = vals[tc.field]
305				}
306				if second == nil {
307					second = vals[tc.field]
308				}
309				spellings := caseSpellings(tc.field)
310				canonical := strconv.Quote(tc.field)
311				firstToken, secondToken := canonical, spellings["upper"]
312				if tc.reversed {
313					firstToken, secondToken = spellings["upper"], canonical
314				}
315				bad := dupEnvelope(t, vals, tc.field, firstToken, secondToken, first, second)
316				writeRawEnvelope(t, dir, bad)
317				requireTopLevelDupCorrupt(t, dir, bad, tc.wantField, secondToken)
318			})
319		}
